// TypeScript minimal streaming client + compatibility shim example
// openai_compat.ts - maps on_delta to Redwood stream events
import fetch from 'node-fetch';

export async function* redwoodStream(url: string, body: any) {
  const res = await fetch(url, { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } });
  if (!res.body) throw new Error('No body');
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buf = '';
  while (true) {
    const { value, done } = await reader.read();
    if (done) {
      if (buf) yield buf;
      break;
    }
    buf += decoder.decode(value, { stream: true });
    // Redwood streams newline-delimited JSON messages (sometimes partial). Reassemble by newline.
    let idx;
    while ((idx = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, idx).trim();
      buf = buf.slice(idx + 1);
      if (!line) continue;
      try {
        const ev = JSON.parse(line);
        yield ev;
      } catch (e) {
        // partial JSON: prepend and continue when more chunks arrive
        buf = line + '\n' + buf;
        break;
      }
    }
  }
}

