// Go example reading chunked stream from Redwood and handling tool call intent
package main

import (
    "bufio"
    "encoding/json"
    "fmt"
    "net/http"
    "os"
)

func main() {
    req, _ := http.NewRequest("POST", "https://api.redwood.ai/v1/generate", nil)
    // ... set body + headers ...
    client := &http.Client{}
    resp, err := client.Do(req)
    if err != nil {
        fmt.Println("request error", err); os.Exit(1)
    }
    defer resp.Body.Close()
    scanner := bufio.NewScanner(resp.Body)
    // Increase buffer if messages are large
    buf := make([]byte, 0, 64*1024)
    scanner.Buffer(buf, 1024*1024)
    for scanner.Scan() {
        line := scanner.Text()
        if len(line) == 0 {
            continue
        }
        var ev map[string]interface{}
        if err := json.Unmarshal([]byte(line), &ev); err != nil {
            // partial chunk or malformed JSON: append to buffer logic could be added
            continue
        }
        if evType, ok := ev["type"].(string); ok && evType == "tool_call.intent" {
            tool := ev["tool"].(string)
            args := ev["args"]
            // synchronous local HTTP call to tool
            go func(t string, a interface{}) {
                // simple POST to local tool runner
                // omitted: build body from args and handle response
                fmt.Println("would call tool:", t, a)
            }(tool, args)
        } else if delta, ok := ev["delta"].(string); ok {
            fmt.Println("delta:", delta)
        }
    }
}
